      f"invalid={len(cases(T.test_validate_authorization_url_rejects_invalid))}, "
      f"reason={len(cases(T.test_rejection_reason))}, "
      f"nonstr={len(cases(T.test_non_string_value_rejected_as_invalid_url))}, "
      f"malformed={len(cases(T.test_audit_prefix_redacts_credentials_in_malformed_url))}, control=1, "
      f"other={3}")
for f in fails:
    print("  FAIL", f)
